import pytest

from app import create_app
from tests.conftest import post_id_from


def test_post_without_csrf_token_rejected(client):
    response = client.post("/auth/login", data={"identifier": "a", "password": "b"})
    assert response.status_code == 400


def test_post_with_wrong_csrf_token_rejected(client):
    client.get("/auth/login")
    response = client.post("/auth/login", data={"identifier": "a", "password": "b", "csrf_token": "wrong"})
    assert response.status_code == 400


def test_authenticated_post_without_csrf_rejected(make_client):
    client, _ = make_client()
    assert client.post("/blog/create", data={"title": "t", "content": "c"}).status_code == 400
    assert client.post("/auth/logout").status_code == 400


def test_security_headers_present(make_client):
    client, _ = make_client()
    response = client.get("/")
    assert "frame-ancestors 'none'" in response.headers["Content-Security-Policy"]
    assert "default-src 'self'" in response.headers["Content-Security-Policy"]
    assert response.headers["X-Content-Type-Options"] == "nosniff"
    assert response.headers["X-Frame-Options"] == "DENY"
    assert response.headers["Cache-Control"] == "no-store"


def test_session_cookie_flags(actions):
    actions.register()
    response = actions.login()
    cookie = response.headers.get("Set-Cookie", "")
    assert "HttpOnly" in cookie
    assert "SameSite=Lax" in cookie


def test_html_in_title_and_content_is_escaped(make_client):
    client, actions = make_client()
    payload = "<script>alert(1)</script>"
    pid = post_id_from(actions.create_post(payload, payload))
    for url in ("/", f"/blog/{pid}"):
        html = client.get(url).get_data(as_text=True)
        assert payload not in html
        assert "&lt;script&gt;" in html


def test_sql_metacharacters_are_inert(make_client):
    client, post_actions = make_client()
    post_actions.create_post("Safe", "content")
    html = client.get("/", query_string={"q": "' OR 1=1 --"}).get_data(as_text=True)
    assert "No blogs found" in html
    assert "Safe" in client.get("/").get_data(as_text=True)


def test_login_sql_injection_attempt_fails(actions):
    actions.register()
    response = actions.login("alice' OR '1'='1", "anything")
    assert response.status_code == 401


def test_oversized_request_returns_413(make_client):
    client, actions = make_client()
    response = actions.post("/blog/create", {"title": "t", "content": "x" * 70_000})
    assert response.status_code == 413


def test_overlong_password_rejected_without_hashing(actions):
    actions.register()
    assert actions.login("alice", "x" * 5000).status_code == 401


def test_app_refuses_to_start_without_secret_key(tmp_path, monkeypatch):
    monkeypatch.delenv("FLASK_DEBUG", raising=False)
    with pytest.raises(RuntimeError):
        create_app({"TESTING": False, "DEBUG": False, "SECRET_KEY": None, "DATABASE": str(tmp_path / "x.db")})


def test_get_on_post_only_route_returns_styled_405(make_client):
    client, _ = make_client()
    response = client.get("/auth/logout")
    assert response.status_code == 405
    assert "Method not allowed" in response.get_data(as_text=True)


def test_post_to_unknown_url_is_404_not_csrf_error(client):
    assert client.post("/nowhere").status_code == 404


def test_error_pages_render_for_anonymous_users(client):
    response = client.get("/does-not-exist")
    assert response.status_code == 404
    assert "Not found" in response.get_data(as_text=True)
